--
-- Table structure for table `appointments`
--

DROP TABLE IF EXISTS `appointments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `appointments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `staff_id` bigint unsigned DEFAULT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `service_id` bigint unsigned DEFAULT NULL,
  `service_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `appointment_date` date NOT NULL,
  `appointment_time` time NOT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `status` enum('pending','approved','completed','cancelled','declined') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `payment_status` enum('unpaid','paid','partial','refunded','partially_refunded') COLLATE utf8mb4_unicode_ci DEFAULT 'unpaid',
  `payment_amount` decimal(10,2) DEFAULT NULL,
  `discount_amount` decimal(10,2) DEFAULT NULL,
  `discount_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `completion_notes` text COLLATE utf8mb4_unicode_ci,
  `decline_reason` text COLLATE utf8mb4_unicode_ci COMMENT 'Reason for declining the appointment',
  `purpose` text COLLATE utf8mb4_unicode_ci,
  `documents` text COLLATE utf8mb4_unicode_ci,
  `identification_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Not specified',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `staff_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `completed_by` bigint unsigned DEFAULT NULL,
  `outcome_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `processed_by` bigint unsigned DEFAULT NULL,
  `payment_date` timestamp NULL DEFAULT NULL,
  `payment_notes` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_appointments_status` (`status`),
  KEY `idx_appointments_user` (`user_id`),
  KEY `idx_appointments_staff` (`staff_id`),
  KEY `idx_appointments_datetime` (`appointment_date`,`appointment_time`),
  KEY `idx_appointments_status_date` (`status`,`appointment_date`),
  KEY `appointments_created_at_index` (`created_at`),
  KEY `appointments_service_id_foreign` (`service_id`),
  KEY `idx_appointments_user_id` (`user_id`),
  KEY `appointments_completed_by_foreign` (`completed_by`),
  KEY `appointments_processed_by_foreign` (`processed_by`),
  CONSTRAINT `appointments_completed_by_foreign` FOREIGN KEY (`completed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointments_processed_by_foreign` FOREIGN KEY (`processed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
